<?php
declare(strict_types=1);

/**
 * install_race_finish_confirmation_v006_20260809_051116pm.php
 *
 * VERSION: v006
 * LAST MODIFIED: 8/9/2026 5:11:16 pm
 *
 * One-time installer for MRL Race Finish Confirmation Monitor v006.
 * This correction restores the original Racing-Reference /race-results/ observation
 * as a separate source while preserving all current v006 sources and cache protection.
 *
 * PHP: 7.3 compatible.
 */

date_default_timezone_set('America/New_York');
header('Content-Type: text/plain; charset=UTF-8');

$baseDir = __DIR__;
$dataDir = $baseDir . '/_race_finish_confirmation';
$backupDir = $dataDir . '/backups/v006_' . date('Ymd_His');
$monitorPath = $baseDir . '/race_finish_confirmation_monitor.php';
$dashboardPath = $baseDir . '/race_finish_confirmation_dashboard.php';
$configPath = $dataDir . '/config.json';

$monitorB64 = '';
$dashboardB64 = '';

function out(string $line = ''): void { echo $line . PHP_EOL; }
function ensure_dir(string $path): bool { return is_dir($path) || @mkdir($path, 0775, true); }
function backup_file(string $path, string $backupDir): bool { if (!is_file($path)) return true; if (!ensure_dir($backupDir)) return false; return @copy($path, $backupDir . '/' . basename($path)); }
function write_atomic(string $path, string $content): bool { $tmp = $path . '.tmp.' . bin2hex(random_bytes(4)); if (@file_put_contents($tmp, $content, LOCK_EX) === false) return false; if (@rename($tmp, $path)) return true; @unlink($tmp); return false; }

out('MRL Race Finish Confirmation Monitor installer v006');
out('Base: ' . $baseDir);
if (!ensure_dir($dataDir) || !ensure_dir($backupDir)) { out('ERROR: could not create data/backup directory.'); exit(1); }
foreach ([$monitorPath, $dashboardPath, $configPath] as $path) { if (is_file($path)) { if (!backup_file($path, $backupDir)) { out('ERROR: could not back up ' . basename($path)); exit(1); } out('BACKUP: ' . basename($path)); } }
$monitor = base64_decode($monitorB64, true); $dashboard = base64_decode($dashboardB64, true);
if (!is_string($monitor) || !is_string($dashboard)) { out('ERROR: embedded package data could not be decoded.'); exit(1); }
if (!write_atomic($monitorPath, $monitor)) { out('ERROR: could not install race_finish_confirmation_monitor.php'); exit(1); } out('INSTALLED: race_finish_confirmation_monitor.php');
if (!write_atomic($dashboardPath, $dashboard)) { out('ERROR: could not install race_finish_confirmation_dashboard.php'); exit(1); } out('INSTALLED: race_finish_confirmation_dashboard.php');
$config = []; if (is_file($configPath)) { $raw = @file_get_contents($configPath); $decoded = is_string($raw) ? json_decode($raw, true) : null; if (is_array($decoded)) $config = $decoded; }
if (!isset($config['sources']) || !is_array($config['sources'])) $config['sources'] = [];
$config['sources']['racing_reference_results'] = ['enabled'=>true,'url_template'=>'https://www.racing-reference.info/race-results/{year}-{race_number}/W'];
$config['sources']['racing_reference_race'] = ['enabled'=>true,'url_template'=>'https://www.racing-reference.info/race/{year}-{race_number}/W'];
$config['sources']['racing_reference_season'] = ['enabled'=>true,'url_template'=>'https://www.racing-reference.info/season-stats/{year}/W'];
if (isset($config['sources']['racing_reference'])) unset($config['sources']['racing_reference']);
if (!write_atomic($configPath, (json_encode($config, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) ?: '{}') . PHP_EOL)) { out('ERROR: could not update _race_finish_confirmation/config.json'); exit(1); } out('UPDATED: _race_finish_confirmation/config.json');
out('VERSION: v006');
out('CORRECTION: Restored separate Racing-Reference Race Results Page monitoring.');
out('CORRECTION: /race-results/{year}-{race_number}/W is now preserved alongside /race/{year}-{race_number}/W.');
out('CORRECTION: Dashboard now shows three independent Racing-Reference tiles.');
out('UNCHANGED: Racing-Reference Season Page and Jayski monitoring.');
out('UNCHANGED: Dashboard no-cache/cache-buster protection.');
out('UNCHANGED: Finish-watch activation/cadence.');
out('UNCHANGED: Scheduler/cron configuration.');
out('UNCHANGED: Existing history/raw files and runtime observations.');
out('UNCHANGED: MRL scoring/final/revision processes.');
out('SUCCESS');
out('Backup: ' . $backupDir);
out('Dashboard: race_finish_confirmation_dashboard.php');
out('Manual test: race_finish_confirmation_monitor.php?force=1');
out('Delete this installer after verification.');
